/* runtime.js -- THE one JS file (RFC-001 §4.0/§4.2), written once.
 *
 * The framework's browser half. A lesson ships: lesson.json (all
 * structure and pedagogy as data), notes.html (prose), lesson.wasm (the
 * physics, via lessons-common's uniform ABI), and a ~15-line HTML stub.
 * This file does the rest: builds the page scaffold from the manifest
 * (header, claims, stages, transport bar, legend, notes, try-this,
 * footer), generates every control and readout, owns the clock, writes
 * params into wasm memory, and paints the primitive buffer back.
 *
 * Uniform wasm ABI (generated by lessons-common::lesson!):
 *   params_ptr() -> f64*     runtime writes params, manifest order
 *   state_at(n) -> len       recompute; pure over the params
 *   prims_ptr(), readouts_ptr()
 *
 * Text (RFC-003), only for lessons built with lesson!(draw, texto) and a
 * manifest that declares "expresiones":
 *   text_ptr(), text_cap(), set_text_len(n)   the student's formulas, UTF-8,
 *                                             one line per box
 *   diag_ptr() -> f64*                        per line [code, column, mask]
 * The page writes what the student types; the LESSON parses it (Rust,
 * crate formulas -- never eval) and answers with numbers only. The
 * messages for the codes live in MENSAJES_FORMULA below, and a cargo
 * test compares them with the Rust table so the two cannot drift.
 *
 * The port (RFC-003): window.physicsLab lets another program read the
 * inputs, set them, and hear every frame -- the studio's recorder
 * (js/estudio.js, loaded only with ?estudio in the URL), a headless
 * renderer, a test. Every frame is a pure function of the inputs, so
 * recording inputs is recording the lesson.
 *
 * Prim records: [0,x,y,st] point · [1,x1,y1,x2,y2,st] segment ·
 * [2,n,pts...,st] polyline · [3,...] arrow · [4,x,y,label,st] label ·
 * [5,x,y,value,decimals,st] number · [9,view] view switch.
 * Geometry views must scale both axes alike (the skew guard throws); a
 * view may declare "uniform": false only where its axes carry different
 * quantities (a phase portrait, a graph) -- a statement, not an escape.
 */
"use strict";

function fatal(title, detail) {
  const d = document.createElement("div");
  d.setAttribute("role", "alert");
  d.style.cssText = "margin:16px auto;max-width:1060px;border:1px solid #e0322a;" +
    "background:rgba(224,50,42,.12);color:#ff4a40;padding:14px 18px;" +
    "font:500 13px/1.6 'JetBrains Mono',monospace;white-space:pre-wrap";
  d.textContent = "This lesson could not start.\n" + title +
    (detail ? "\n\n" + detail : "");
  document.body.prepend(d);
}

/* formulas::Codigo -> what the page says. Keep each line exactly
 * `N: "message",` -- formulas' test la_pagina_tiene_los_mismos_mensajes
 * reads this file and compares every line with Codigo::mensaje. */
const MENSAJES_FORMULA = {
  1: "escribe una fórmula",
  2: "ese carácter no es parte de una fórmula",
  3: "no conozco ese nombre",
  4: "este paréntesis nunca se cierra",
  5: "este paréntesis cierra algo que nadie abrió",
  6: "aquí falta un valor",
  7: "las funciones llevan paréntesis: sin(t)",
  8: "ese número está mal escrito",
  9: "número pegado: ¿quisiste ^ o ·?",
  10: "demasiados paréntesis anidados",
  11: "el decimal va con punto: 0.5",
};

(async function () {
  const NS = "http://www.w3.org/2000/svg";

  if (location.protocol === "file:") {
    fatal("Opened as a file:// URL, where the browser blocks loading the " +
          "lesson's data and WebAssembly.",
          "Serve the site instead (any static server works):\n" +
          "    cd physics-lab/public && python3 -m http.server 8000\n" +
          "then open http://localhost:8000/");
    return;
  }

  const base = document.querySelector("script[data-lesson]").dataset.lesson;

  let lesson, wasm, notesHtml;
  try {
    lesson = await (await fetch(base + "/lesson.json")).json();
    notesHtml = lesson.notes
      ? await (await fetch(base + "/" + lesson.notes)).text()
      : "";
    const bytes = await (await fetch(base + "/lesson.wasm")).arrayBuffer();
    const { instance } = await WebAssembly.instantiate(bytes, {});
    wasm = instance.exports;
  } catch (e) {
    fatal("Loading the lesson failed: " + e,
          "If this is a Content-Security-Policy error, script-src needs " +
          "'wasm-unsafe-eval' (set in this site's _headers).");
    return;
  }
  try {

  // ---- scaffold: the whole page from the manifest -------------------------
  const root = document.getElementById("lesson");
  const h = (tag, cls, html) => {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html !== undefined) e.innerHTML = html;
    return e;
  };

  const header = h("header");
  header.append(
    h("div", "eyebrow", lesson.eyebrow || "Goosethropic Physics"),
    h("h1", "", lesson.title),
    h("p", "lede", lesson.lede || ""));
  root.append(header);

  if (lesson.claims && lesson.claims.length) {
    const c = h("div", "claims");
    for (const cl of lesson.claims) {
      c.append(h("div", "claim-row",
        "<span class='cid'>" + cl.id + "</span> " + cl.text +
        (cl.test ? " <span class='ctest'>" + cl.test + "</span>" : "")));
    }
    root.append(c);
  }

  // ---- formula boxes (RFC-003): what the student writes -------------------
  const exprs = lesson.expresiones || [];
  const hasText = exprs.length > 0;
  if (hasText && !wasm.text_ptr) {
    throw new Error("runtime: lesson.json declares \"expresiones\" but lesson.wasm " +
      "exports no text_ptr -- build the lesson with lesson!(draw, texto)");
  }
  if (exprs.length > 8) {   // lessons-common DIAG_SLOTS: one diagnostics line per box
    throw new Error("runtime: at most 8 \"expresiones\" (DIAG_SLOTS), got " + exprs.length);
  }
  const exprInputs = [], diagEls = [];
  if (hasText) {
    const box = h("div", "panel exprs");
    exprs.forEach((ex, i) => {
      const row = h("div", "expr");
      const lab = h("label", "k", ex.etiqueta);
      lab.htmlFor = "e-" + i;
      const inp = document.createElement("input");
      inp.type = "text";
      inp.id = "e-" + i;
      inp.className = "fx";
      inp.value = ex.valor || "";
      inp.placeholder = ex.placeholder || "";
      inp.spellcheck = false;
      inp.autocomplete = "off";
      inp.setAttribute("autocapitalize", "off");
      const dg = h("pre", "diag");
      dg.id = "d-" + i;
      dg.setAttribute("aria-live", "polite");
      inp.setAttribute("aria-describedby", dg.id);
      inp.addEventListener("input", () => { textDirty = true; draw(); });
      row.append(lab, inp, dg);
      box.append(row);
      exprInputs.push(inp);
      diagEls.push(dg);
    });
    root.append(box);
  }

  const stages = h("div", "stages");
  lesson.views.forEach((v, i) => {
    const st = h("div", "stage" + (v.wide ? " wide" : ""));
    if (v.title) {
      st.append(h("div", "stagehead",
        "<h2>" + v.title + "</h2>" +
        (v.law ? "<span class='law'>" + v.law + "</span>" : "")));
    }
    const svg = document.createElementNS(NS, "svg");
    svg.setAttribute("viewBox", "0 0 " + v.viewBox.w + " " + v.viewBox.h);
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", lesson.title);
    const g = document.createElementNS(NS, "g");
    g.id = "scene" + i;
    svg.append(g);
    st.append(svg);
    stages.append(st);
  });
  root.append(stages);

  if (lesson.steps && lesson.steps.length) {
    const dv = h("div", "panel deriv");
    const nav = h("div", "deriv-nav",
      "<button id='prev'>&larr; Prev</button>" +
      "<span class='stepno' id='stepno'></span>" +
      "<button id='next'>Next &rarr;</button>");
    dv.append(nav);
    lesson.steps.forEach((st, i) => {
      const sec = h("div", "step",
        "<h3>" + st.title + "</h3>" + st.html);
      sec.dataset.step = i + 1;
      sec.hidden = i !== 0;
      dv.append(sec);
    });
    root.append(dv);
  }

  const bar = h("div", "bar");
  const ctlBox = h("div", "");
  ctlBox.id = "controls";
  if (lesson.sweep) {
    ctlBox.append(
      h("div", "",
        "<label class='k'>Playback</label><div class='row'>" +
        "<button id='play'>" + lesson.sweep.label + "</button></div>"),
      h("div", "",
        "<label class='k'>Speed</label>" +
        "<div class='speed' role='group' aria-label='Playback speed'>" +
        "<button data-rate='0.25'>0.25&times;</button>" +
        "<button data-rate='1' aria-pressed='true'>1&times;</button>" +
        "<button data-rate='2'>2&times;</button></div>"));
  }
  bar.append(ctlBox);
  const roBox = h("dl", "");
  roBox.id = "readouts";
  bar.append(roBox);
  root.append(bar);

  if (lesson.legend && lesson.legend.length) {
    const lg = h("div", "panel");
    const row = h("div", "legend");
    for (const item of lesson.legend) {
      const sw = lesson.styles[item.style];
      row.append(h("span", "",
        "<i class='swatch' style='background:var(" + sw.var + ")'></i> " + item.label));
    }
    lg.append(row);
    root.append(lg);
  }

  if (notesHtml) root.append(h("div", "panel", notesHtml));

  if (lesson.tryThis && lesson.tryThis.length) {
    const tp = h("div", "panel");
    tp.append(h("div", "tryhead", "Try this"));
    const ul = h("ul", "trylist");
    for (const t of lesson.tryThis) ul.append(h("li", "", t));
    tp.append(ul);
    root.append(tp);
  }

  root.append(h("footer", "",
    "<a href='../../index.html'>&larr; Physics lab</a>" +
    (lesson.footer ? " &middot; " + lesson.footer : "")));

  // ---- world <-> screen, per view ----------------------------------------
  function mapping(world, vb, uniform, label) {
    const mx = vb.w / (world.x1 - world.x0), my = vb.h / (world.y1 - world.y0);
    if (uniform !== false && Math.abs(mx - my) > 1e-9 * Math.max(mx, my)) {
      throw new Error("runtime: non-uniform world scale in " + label +
        " (" + mx + " vs " + my + ")");
    }
    return {
      sx: x => (x - world.x0) * mx,
      sy: y => vb.h - (y - world.y0) * my,
    };
  }
  const views = lesson.views.map((v, i) => ({
    map: mapping(v.world, v.viewBox, v.uniform, "view " + i),
    scene: document.getElementById("scene" + i),
  }));

  // ---- controls generated from the manifest ------------------------------
  // widget "hidden": no slider (e.g. the stepper's param).
  // widget "auto":   shown only while some formula names it -- write an
  //                  `a` and its slider appears, Desmos-style (RFC-003).
  const state = {};
  const ctl = {};
  const autos = [];
  const updaters = [];
  Object.entries(lesson.params).forEach(([key, p], idx) => {
    state[key] = p.value;
    if (p.widget === "hidden") return;
    const wrap = document.createElement("div");
    const lab = document.createElement("label");
    lab.className = "k";
    lab.htmlFor = "p-" + key;
    lab.innerHTML = p.label + ' <span class="val" id="p-' + key + 'lab"></span>';
    const input = document.createElement("input");
    input.type = "range";
    input.id = "p-" + key;
    input.min = p.min; input.max = p.max; input.step = p.step; input.value = p.value;
    // By class, not "the first span": a label may carry its own spans
    // (math marked class='m'), and the value must not overwrite them.
    const out = lab.querySelector(".val");
    ctl[key] = { input, out, p };
    const upd = () => {
      state[key] = +input.value;
      out.textContent = (+input.value).toFixed(p.digits ?? 2) + (p.unit ? " " + p.unit : "");
      draw();
    };
    input.addEventListener("input", () => { if (sweep) stopSweep(); upd(); });
    wrap.append(lab, input);
    if (p.widget === "auto") {
      wrap.hidden = true;
      autos.push({ bit: 1 << idx, wrap });
    }
    ctlBox.appendChild(wrap);
    updaters.push(upd);
  });
  // A control shows what `state` holds -- for changes that did not come
  // from its own slider (the sweep, the port).
  function showValue(key) {
    const c = ctl[key];
    if (!c) return;
    c.input.value = state[key];
    c.out.textContent = (+state[key]).toFixed(c.p.digits ?? 2) + (c.p.unit ? " " + c.p.unit : "");
  }

  // ---- readouts generated from the manifest ------------------------------
  // An unknown fmt is a load-time error, not a silent fix3: a readout
  // that cannot say what its manifest asked for is a page that lies.
  const FMT = {
    turns3: v => v.toFixed(3) + " τ",
    fix0: v => v.toFixed(0),
    fix1: v => v.toFixed(1),
    fix2: v => v.toFixed(2),
    fix3: v => v.toFixed(3),
    sci: v => (v === 0 ? "0" : v.toExponential(1)),
  };
  const roEls = [];
  for (const r of lesson.readouts) {
    const f = FMT[r.fmt ?? "fix3"];
    if (!f) {
      throw new Error("runtime: readout \"" + r.label + "\" asks for fmt \"" + r.fmt +
        "\"; known: " + Object.keys(FMT).join(", "));
    }
    const d = h("div", "num" + (r.hero ? " hero" : ""),
      "<dt>" + r.label + "</dt><dd>&mdash;</dd>");
    roBox.appendChild(d);
    roEls.push({ slot: r.slot, f, unit: r.unit, el: d.querySelector("dd") });
  }

  // ---- painting ----------------------------------------------------------
  const styles = lesson.styles;
  function css(st) { return "var(" + styles[st | 0].var + ")"; }
  function el(name, attrs) {
    const e = document.createElementNS(NS, name);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    return e;
  }

  function paint(buf, n) {
    for (const v of views) v.scene.textContent = "";
    let view = views[0];
    let i = 0;
    while (i < n) {
      const tag = buf[i];
      const { sx, sy } = view.map;
      if (tag === 9) {
        view = views[buf[i + 1] | 0];
        i += 2;
      } else if (tag === 0) {
        view.scene.appendChild(el("circle", { cx: sx(buf[i+1]), cy: sy(buf[i+2]),
          r: 4.5, fill: css(buf[i+3]) }));
        i += 4;
      } else if (tag === 2) {
        const cnt = buf[i + 1] | 0;
        const st = buf[i + 2 + 2 * cnt];
        const s = styles[st | 0];
        let pts = "";
        for (let j = 0; j < cnt; j++) {
          pts += (j ? " " : "") + sx(buf[i + 2 + 2*j]).toFixed(2) + "," +
                 sy(buf[i + 3 + 2*j]).toFixed(2);
        }
        view.scene.appendChild(el("polyline", { points: pts, fill: "none",
          stroke: css(st), "stroke-width": s.width ?? 2,
          "stroke-dasharray": s.dash ? "6 5" : "none",
          "stroke-linejoin": "round", "stroke-linecap": "round" }));
        i += 3 + 2 * cnt;
      } else if (tag === 1 || tag === 3) {
        const [x1, y1, x2, y2, st] = [buf[i+1], buf[i+2], buf[i+3], buf[i+4], buf[i+5]];
        const s = styles[st | 0];
        view.scene.appendChild(el("line", { x1: sx(x1), y1: sy(y1),
          x2: sx(x2), y2: sy(y2), stroke: css(st), "stroke-width": s.width ?? 2,
          "stroke-dasharray": s.dash ? "6 5" : "none", "stroke-linecap": "round" }));
        if (tag === 3) {
          const ang = Math.atan2(sy(y2) - sy(y1), sx(x2) - sx(x1));
          const L = 11, Wd = 4.5;
          const hx = sx(x2), hy = sy(y2);
          view.scene.appendChild(el("path", {
            d: "M " + hx + " " + hy +
               " L " + (hx - L * Math.cos(ang) + Wd * Math.sin(ang)) + " " +
                       (hy - L * Math.sin(ang) - Wd * Math.cos(ang)) +
               " L " + (hx - L * Math.cos(ang) - Wd * Math.sin(ang)) + " " +
                       (hy - L * Math.sin(ang) + Wd * Math.cos(ang)) + " Z",
            fill: css(st) }));
        }
        i += 6;
      } else if (tag === 4 || tag === 5) {
        // Texto. La lección manda CUÁL y DÓNDE; la página manda qué dice.
        // Por eso el buffer sigue siendo de puros f64 y aun así se puede
        // escribir «ángulo», «tensión» o «30°»: las cadenas viven en
        // lesson.json, en UTF-8, y aquí las pinta una fuente de verdad.
        const st = tag === 4 ? buf[i + 4] : buf[i + 5];
        const s = styles[st | 0];
        const t = el("text", {
          x: sx(buf[i + 1]), y: sy(buf[i + 2]),
          fill: css(st), "font-size": s.size ?? 20,
          "font-family": "var(--mono, ui-monospace, monospace)",
          "text-anchor": "middle", "dominant-baseline": "middle",
          "paint-order": "stroke", stroke: "var(--paper, #f4efe3)",
          "stroke-width": 4, "stroke-linejoin": "round"
        });
        if (tag === 4) {
          const labels = lesson.labels || [];
          t.textContent = labels[buf[i + 3] | 0] ?? "";
          i += 5;
        } else {
          t.textContent = buf[i + 3].toFixed(buf[i + 4] | 0);
          i += 6;
        }
        view.scene.appendChild(t);
      } else {
        throw new Error("runtime: unknown prim tag " + tag);
      }
    }
  }

  // ---- text: formulas into wasm memory, diagnostics back -----------------
  const enc = new TextEncoder();
  const DIAG_ANCHO = 3;
  let textDirty = hasText;
  const lastDiag = [], lastMask = [];
  function writeText() {
    let bytes = enc.encode(exprInputs.map(i => i.value).join("\n"));
    const cap = wasm.text_cap();
    // Past the cap the lesson reads the longest whole-letter prefix.
    if (bytes.length > cap) bytes = bytes.subarray(0, cap);
    new Uint8Array(wasm.memory.buffer, wasm.text_ptr(), bytes.length).set(bytes);
    wasm.set_text_len(bytes.length);
  }
  function readDiag() {
    const dg = new Float64Array(wasm.memory.buffer, wasm.diag_ptr(),
      exprInputs.length * DIAG_ANCHO);
    exprInputs.forEach((inp, i) => {
      const code = dg[i * DIAG_ANCHO], col = dg[i * DIAG_ANCHO + 1];
      // A caret under the column, compiler-style. Not n−1 spaces: glyphs
      // like − or τ fall outside the self-hosted font subsets and render
      // in a fallback font of another width. The same prefix, invisible,
      // is exactly as wide as the visible one, whatever font draws it.
      const prefix = code ? [...inp.value].slice(0, Math.max(0, col - 1)).join("") : "";
      const msg = code ? "^ " + (MENSAJES_FORMULA[code] ?? "error " + code) : "";
      if (msg + "\u0000" + prefix !== lastDiag[i]) {
        lastDiag[i] = msg + "\u0000" + prefix;
        diagEls[i].replaceChildren();
        if (code) {
          const pad = document.createElement("span");
          pad.className = "pad";
          pad.textContent = prefix;
          diagEls[i].append(pad, msg);
          inp.setAttribute("aria-invalid", "true");
        } else {
          inp.removeAttribute("aria-invalid");
        }
      }
      // Half-typed formulas keep their last good mask: a slider must not
      // blink out while its letter is being typed around.
      if (!code) lastMask[i] = dg[i * DIAG_ANCHO + 2];
    });
    const mask = lastMask.reduce((m, v) => m | (v ?? 0), 0);
    for (const a of autos) {
      const show = (mask & a.bit) !== 0;
      if (a.wrap.hidden === show) a.wrap.hidden = !show;
    }
  }

  // ---- the frame: params into wasm memory, prims back --------------------
  // draw() runs from listeners and rAF, i.e. OUTSIDE the startup try
  // block, so it guards itself: a wasm trap (e.g. a lesson overflowing
  // PRIM_CAP) must reach the page, not just the console. The instance
  // survives a trap -- state_at rewrites from index 0 -- so we disarm
  // the clock and let the reader retry by moving a control.
  const keys = Object.keys(lesson.params);
  const listeners = [];
  let drawFailed = false;
  function draw() {
    try { drawUnguarded(); drawFailed = false; }
    catch (e) {
      if (!drawFailed) {
        drawFailed = true;
        sweep = false;
        fatal("A frame failed inside the lesson's WebAssembly: " + e,
              "Params at failure: " + JSON.stringify(state) +
              (hasText ? "\nFormulas: " + JSON.stringify(exprInputs.map(i => i.value)) : "") +
              "\nA RuntimeError here usually means the lesson exceeded " +
              "PRIM_CAP (8192 f64s) or panicked in draw().");
      }
      return;
    }
    // Port clients run OUTSIDE that guard: a broken recorder is reported
    // as itself, not blamed on the lesson's WebAssembly -- and detached,
    // so it cannot fail again on every frame.
    for (const f of listeners.slice()) {
      try { f(); }
      catch (e) {
        listeners.splice(listeners.indexOf(f), 1);
        fatal("A client of window.physicsLab failed and was detached: " + e);
      }
    }
  }
  function drawUnguarded() {
    if (textDirty) { writeText(); textDirty = false; }
    const pv = new Float64Array(wasm.memory.buffer, wasm.params_ptr(), keys.length);
    keys.forEach((k, i) => { pv[i] = state[k] * (lesson.params[k].scale ?? 1); });
    const n = wasm.state_at(keys.length);
    paint(new Float64Array(wasm.memory.buffer, wasm.prims_ptr(), n), n);
    const rd = new Float64Array(wasm.memory.buffer, wasm.readouts_ptr(), 8);
    for (const r of roEls) {
      const v = rd[r.slot];
      r.el.textContent = Number.isFinite(v) ? r.f(v) + (r.unit ? " " + r.unit : "") : "—";
    }
    if (hasText) readDiag();
  }

  // ---- sweep clock -------------------------------------------------------
  let sweep = false, rate = 1, last = null;
  const sw = lesson.sweep;
  const btn = document.getElementById("play");
  function stopSweep() { sweep = false; if (btn) btn.textContent = sw.label; }
  if (sw && btn) {
    btn.addEventListener("click", () => {
      sweep = !sweep;
      btn.textContent = sweep ? "Pause" : sw.label;
    });
    document.querySelectorAll(".speed button").forEach(b =>
      b.addEventListener("click", () => {
        rate = +b.dataset.rate;
        document.querySelectorAll(".speed button").forEach(o =>
          o.setAttribute("aria-pressed", String(o === b)));
      }));
    (function tick(ts) {
      if (last === null) last = ts;
      const dt = Math.min(60, ts - last) / 1000; last = ts;
      if (sweep) {
        const p = lesson.params[sw.param];
        let v = state[sw.param] + sw.rate * dt * rate;
        const span = p.max - p.min;
        v = p.min + ((v - p.min) % span + span) % span;
        state[sw.param] = v;
        showValue(sw.param);
        draw();
      }
      requestAnimationFrame(tick);
    })(performance.now());
  }

  // ---- stepper wiring (drives the hidden step param) ---------------------
  if (lesson.steps && lesson.stepParam) {
    const total = lesson.steps.length;
    const show = () => {
      const cur = state[lesson.stepParam];
      document.querySelectorAll(".step").forEach(d => {
        d.hidden = +d.dataset.step !== cur;
      });
      document.getElementById("stepno").textContent = cur + " / " + total;
      document.getElementById("prev").disabled = cur === 1;
      document.getElementById("next").disabled = cur === total;
      draw();
    };
    document.getElementById("prev").addEventListener("click", () => {
      if (state[lesson.stepParam] > 1) { state[lesson.stepParam]--; show(); }
    });
    document.getElementById("next").addEventListener("click", () => {
      if (state[lesson.stepParam] < total) { state[lesson.stepParam]++; show(); }
    });
    show();
  }

  // ---- the port: inputs out, inputs in, every frame announced ------------
  // An input state is {p: [values in manifest order], x: [formula texts]}.
  // aplica() sets it and draws synchronously, so frame(state) is a pure
  // function a recorder can replay at any instant, at any frame rate.
  window.physicsLab = Object.freeze({
    version: 1,
    leccion: lesson.slug,
    params: Object.freeze(keys.slice()),
    expresiones: exprInputs.length,
    estado() {
      return { p: keys.map(k => state[k]), x: exprInputs.map(i => i.value) };
    },
    aplica(s) {
      if (s && Array.isArray(s.p)) {
        keys.forEach((k, i) => {
          if (typeof s.p[i] === "number") { state[k] = s.p[i]; showValue(k); }
        });
      }
      if (s && Array.isArray(s.x)) {
        exprInputs.forEach((inp, i) => {
          if (typeof s.x[i] === "string" && inp.value !== s.x[i]) {
            inp.value = s.x[i];
            textDirty = true;
          }
        });
      }
      draw();
      return !drawFailed;
    },
    alCuadro(f) { listeners.push(f); },
    detenerReloj() { if (sweep) stopSweep(); },
  });

  for (const f of updaters) f();
  draw();
  if (new URLSearchParams(location.search).has("estudio")) {
    // The studio is a client of the port, not part of the lesson: a
    // student's page never downloads it.
    import("./estudio.js").then(m => m.monta(window.physicsLab, bar)).catch(e =>
      fatal("The studio (js/estudio.js) failed to load: " + e));
  }
  } catch (e) {
    fatal("The lesson loaded but failed while starting: " + e,
          e && e.stack ? String(e.stack).split("\n").slice(0, 3).join("\n") : "");
  }
})();
